use vstd::prelude::*;

verus! {

spec fn divides(d: int, n: int) -> bool {
    d != 0 && n % d == 0
}

spec fn is_prime_spec(n: int) -> bool {
    n >= 2
    && forall|k: int| 2 <= k < n ==> !divides(k, n)
}

fn is_prime(n: i8) -> (res: bool)
    ensures
        res == is_prime_spec(n as int),
{
    // By definition, primes are >= 2.
    if n < 2 {
        assert((n as int) < 2);
        assert(!is_prime_spec(n as int));
        return false;
    }

    // Now n is in [2, 127]. We'll test divisors k in [2, n).
    let n_i32 = n as i32;
    let mut k: i32 = 2;

    while k < n_i32
        invariant
            2 <= n_i32,                       // since n >= 2
            2 <= k <= n_i32,
            forall|d: int|
                2 <= d < (k as int) ==> !divides(d, n_i32 as int),
        decreases (n_i32 - k),
    {
        if n_i32 % k == 0 {
            // Exhibit divisor k to refute primality
            assert(divides(k as int, n_i32 as int));
            assert(!is_prime_spec(n_i32 as int));
            return false;
        }
        k += 1; // termination measure (n - k) strictly decreases
    }

    // From loop exit: k >= n_i32, and we have checked all d in [2, k)
    assert(k as int >= n_i32 as int);
    assert(forall|d: int| 2 <= d < (n_i32 as int) ==> !divides(d, n_i32 as int));
    assert(is_prime_spec(n_i32 as int));

    true
}

} // verus!

